import axios from 'axios';
export async function searchAll(q, signal) {
  if (!q?.trim()) return { products: [], categories: [], sellers: [] };
  const { data } = await axios.get('/api/search', { params: { q }, signal });
  return data;
}
export const getProduct = async (id) => (await axios.get(`/api/products/${id}`)).data;
export const getCategoryProducts = async (id) => (await axios.get(`/api/categories/${id}/products`)).data;
export const getSeller = async (id) => (await axios.get(`/api/sellers/${id}`)).data;
export const postSellerVisit = async (id) => axios.post(`/api/sellers/${id}/visit`);
